-- V20__create_expert_reviews.sql -- G3-T13: Expert Review table -- -- Stores expert review decisions on Safety Events. Each row represents -- ONE review submission by ONE reviewer on ONE event. Reviews are -- append-only (no edit, no delete). -- -- Relationship: safety_events (1) --< (N) expert_reviews --   FK on safety_event_id: ON DELETE CASCADE  -  if the event is ever --   removed (approved retention task), the review rows follow it. -- -- Decision values sourced from: --   * docs/04_SAFETY_AND_CBT_RULES.md (section 9): CONTINUE_MONITORING, --     REQUEST_FOLLOWUP, ESCALATE, DISMISS --   * docs/02_DATABASE_MVP.md (section 6.4): same four values --   * G3-T13 task query: CONFIRM_RISK, DOWNGRADE_RISK, NO_ACTION -- -- CONFIRM_RISK / DOWNGRADE_RISK are ADVISORY ONLY  -  they do NOT -- automatically change safety_events.risk_level. The system's risk state -- is only modified through the Safety Resolver pipeline (G3-T10). -- Expert reviews are recorded for audit purposes. -- -- No updated_at column  -  reviews are append-only per Safety history rules.  CREATE TABLE expert_reviews (     id              UUID         PRIMARY KEY,     safety_event_id UUID         NOT NULL         REFERENCES safety_events(id) ON DELETE CASCADE,     reviewer_id     UUID         NOT NULL         REFERENCES users(id) ON DELETE RESTRICT,     decision        VARCHAR(30)  NOT NULL,     note            TEXT         NULL,     created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),      -- One review per reviewer per event (prevent duplicate submissions)     CONSTRAINT expert_reviews_event_reviewer_uq         UNIQUE (safety_event_id, reviewer_id),      CONSTRAINT expert_reviews_decision_chk         CHECK (decision IN (             'CONFIRM_RISK',             'DOWNGRADE_RISK',             'ESCALATE',             'NO_ACTION',             'CONTINUE_MONITORING',             'REQUEST_FOLLOWUP',             'DISMISS'         )) );  -- Hot path 1: "list all reviews for this event" (event detail screen) CREATE INDEX expert_reviews_event_idx     ON expert_reviews (safety_event_id);  -- Hot path 2: "list all reviews by this reviewer" (reviewer workload view) CREATE INDEX expert_reviews_reviewer_idx     ON expert_reviews (reviewer_id);  -- Hot path 3: audit - "all reviews in time order" (chronological view) CREATE INDEX expert_reviews_created_at_idx     ON expert_reviews (created_at);